package rig;
import com.etheller.warsmash.viewer5.handlers.w3x.War3MapViewer;
/** FRAMETIMES=1: how long each frame took (after the first 300 map frames), as percentiles, and the worst frames. */
public class FrameStats {
  static long lastNs = 0; static int lastTick = -1; static final java.util.List<long[]> frameTimes = new java.util.ArrayList<>();
  public static void frame(War3MapViewer v, int n, int last) {
    if (System.getenv("FRAMETIMES") != null) { long now = System.nanoTime(); if (lastNs != 0 && n > 300) { Main.frameDone(now - lastNs); int tk = v.simulation.getGameTurnTick(); frameTimes.add(new long[]{now - lastNs, n, tk, tk != lastTick ? 1 : 0}); lastTick = tk; } lastNs = now;
      if (n == 301) { java.util.Arrays.fill(com.etheller.warsmash.viewer5.handlers.w3x.simulation.CSimulation.stageWorst, 0); com.etheller.warsmash.viewer5.handlers.w3x.simulation.CSimulation.pathfindingSliceWorst = 0; com.etheller.warsmash.viewer5.handlers.w3x.simulation.pathing.CPathfindingProcessor.pathFoundWorst = 0; }
      if (n >= last) { StringBuilder sw = new StringBuilder("RIG: STAGES worst simulation-step time per part, us:"); for (int i = 0; i < com.etheller.warsmash.viewer5.handlers.w3x.simulation.CSimulation.STAGE_NAMES.length; i++) sw.append(' ').append(com.etheller.warsmash.viewer5.handlers.w3x.simulation.CSimulation.STAGE_NAMES[i]).append('=').append(com.etheller.warsmash.viewer5.handlers.w3x.simulation.CSimulation.stageWorst[i] / 1000); sw.append(" | pathFound worst=").append(com.etheller.warsmash.viewer5.handlers.w3x.simulation.pathing.CPathfindingProcessor.pathFoundWorst / 1000).append(" | pathfinding slice worst=").append(com.etheller.warsmash.viewer5.handlers.w3x.simulation.CSimulation.pathfindingSliceWorst / 1000); System.err.println(sw); frameTimes.sort((a, b) -> Long.compare(a[0], b[0])); int c = frameTimes.size(); if (c > 0) { System.err.println("RIG: FRAMETIMES frames " + c + " median " + frameTimes.get(c / 2)[0] / 1000 + " us, p95 " + frameTimes.get(c * 95 / 100)[0] / 1000 + " us, p99 " + frameTimes.get(c * 99 / 100)[0] / 1000 + " us, max " + frameTimes.get(c - 1)[0] / 1000 + " us; frames over 16.6 ms: " + frameTimes.stream().filter(a -> a[0] > 16_600_000L).count() + ", over 33 ms: " + frameTimes.stream().filter(a -> a[0] > 33_000_000L).count()); java.util.List<long[]> tf = new java.util.ArrayList<>(); for (long[] a : frameTimes) if (a[3] == 1) tf.add(a); tf.sort((a, b) -> Long.compare(a[0], b[0])); int tc = tf.size(); if (tc > 0) System.err.println("RIG: FRAMETIMES simulation-step frames " + tc + " median " + tf.get(tc / 2)[0] / 1000 + " us, p95 " + tf.get(tc * 95 / 100)[0] / 1000 + " us, p99 " + tf.get(tc * 99 / 100)[0] / 1000 + " us, max " + tf.get(tc - 1)[0] / 1000 + " us"); for (int i = 1; i <= 8 && i <= c; i++) System.err.println("RIG: FRAMETIMES worst " + frameTimes.get(c - i)[0] / 1000 + " us at frame " + frameTimes.get(c - i)[1] + " tick " + frameTimes.get(c - i)[2]); } } }
  }
}
